#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.assign(n, 0);
    if (n == 0) return;

    int maxThreads = 1;
#ifdef _OPENMP
    maxThreads = omp_get_max_threads();
#endif

    std::vector<long long> blockSums(maxThreads, 0);

#pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        // Map threads to contiguous chunks [start, end)
        const int base = n / nt;
        const int rem  = n % nt;
        const int start = tid * base + (tid < rem ? tid : rem);
        const int count = base + (tid < rem ? 1 : 0);
        const int end   = start + count;

        // Phase 1: local reverse-prefix within each block (exclusive of later blocks)
        long long localSum = 0;
        for (int i = end - 1; i >= start; --i) {
            localSum += static_cast<long long>(x[i]);
            output[i] = static_cast<int>(localSum);
        }
        blockSums[tid] = localSum;

#pragma omp barrier

        // Phase 2: compute the sum of all blocks to the right of this one
        long long add = 0;
        for (int t = tid + 1; t < nt; ++t) add += blockSums[t];

        // Phase 3: add that offset to each element in this block
        if (add != 0) {
            for (int i = start; i < end; ++i) {
                output[i] = static_cast<int>(static_cast<long long>(output[i]) + add);
            }
        }
    }
}
