#include <vector>
#include <cstddef>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const std::size_t n = x.size();
    output.assign(n, 0);
    if (n == 0) return;

    // Parallel, race-free two-phase scheme:
    // 1) Each thread computes reverse-prefix sums within its own contiguous block,
    //    and writes its block total to blockSums[tid].
    // 2) A single thread computes offsets (sum of blocks to the right) and stores
    //    them into offsets[tid].
    // 3) Each thread adds its offset to its block outputs.
#pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        // Allocate shared arrays once, by a single thread, then barrier.
        static std::vector<long long> blockSums;
        static std::vector<long long> offsets;

#pragma omp single
        {
            blockSums.assign(static_cast<std::size_t>(nt), 0LL);
            offsets.assign(static_cast<std::size_t>(nt), 0LL);
        }

#pragma omp barrier

        // Contiguous block partitioning
        const std::size_t base = n / static_cast<std::size_t>(nt);
        const std::size_t rem  = n % static_cast<std::size_t>(nt);
        const std::size_t start = static_cast<std::size_t>(tid) * base +
                                  static_cast<std::size_t>(tid < static_cast<int>(rem) ? tid : static_cast<int>(rem));
        const std::size_t count = base + (static_cast<std::size_t>(tid) < rem ? 1u : 0u);
        const std::size_t end   = start + count;

        // Phase 1: local reverse-prefix within [start, end)
        long long local = 0;
        for (std::size_t idx = end; idx > start; --idx) {
            const std::size_t i = idx - 1;
            local += static_cast<long long>(x[i]);
            output[i] = static_cast<int>(local);
        }
        blockSums[static_cast<std::size_t>(tid)] = local;

#pragma omp barrier

        // Phase 2: compute per-thread offsets in a single thread (deterministic, no races)
#pragma omp single
        {
            long long runningRight = 0;
            // offsets[t] = sum of blockSums for blocks with index > t
            for (int t = nt - 1; t >= 0; --t) {
                offsets[static_cast<std::size_t>(t)] = runningRight;
                runningRight += blockSums[static_cast<std::size_t>(t)];
            }
        }

#pragma omp barrier

        // Phase 3: add offset to each element in the block
        const long long add = offsets[static_cast<std::size_t>(tid)];
        if (add != 0) {
            for (std::size_t i = start; i < end; ++i) {
                output[i] = static_cast<int>(static_cast<long long>(output[i]) + add);
            }
        }
    }
}
